Task ID: repair_pfs_l1_tcp_telnet_drop
Category: packet_filtering_security
Difficulty: level_1

Original Instruction:
Fix the XDP program to compile and drop IPv4 TCP packets destined to Telnet port 23, while passing all other traffic (other TCP ports, UDP, ICMP, non-IPv4, and malformed packets).

Technical Requirements:
- Check Ethernet and IPv4 bounds
- Verify Ethernet protocol is ETH_P_IP (0x0800)
- Verify IP protocol is IPPROTO_TCP
- Parse variable IHL (ip->ihl * 4) safely
- Include required headers <linux/tcp.h>
- Drop packets with TCP dport 23; return XDP_PASS for other packets
- GPL license and SEC("xdp") entry point

Previous Implementation:
```c
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/in.h>
#include <linux/ip.h>
#include <bpf/bpf_endian.h>
#include <bpf/bpf_helpers.h>

SEC("xdp")
int xdp_filter(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;
    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;
    if (ip->ihl < 5)
        return XDP_PASS;
    __u32 ip_len = (__u32)ip->ihl * 4;
    if ((void *)ip + ip_len > data_end)
        return XDP_PASS;
    if (ip->protocol != IPPROTO_TCP)
        return XDP_PASS;

    struct tcphdr *tcp = (void *)ip + ip_len;
    if ((void *)(tcp + 1) > data_end)
        return XDP_PASS;

    if (tcp->dest == bpf_htons(23))
        return XDP_DROP;

    return XDP_PASS;
}

char LICENSE[] SEC("license") = "GPL";
```

Diagnostic Output:
```text
faulty.c:26:12: error: variable has incomplete type 'struct tcphdr'
    struct tcphdr *tcp = (void *)ip + ip_len;
           ^
faulty.c:26:12: note: forward declaration of 'struct tcphdr'
faulty.c:27:18: error: invalid application of 'sizeof' to an incomplete type 'struct tcphdr'
    if ((void *)(tcp + 1) > data_end)
                 ^~~~~~~
faulty.c:30:12: error: member access into incomplete type 'struct tcphdr'
    if (tcp->dest == bpf_htons(23))
           ^
3 errors generated.
```

Please provide the corrected, complete, and self-contained C source code for this XDP program.

