Task ID: repair_pfs_l1_tcp_port_range_drop
Category: packet_filtering_security
Difficulty: level_1

Original Instruction:
Fix the verifier bounds check so the program correctly parses the TCP header and drops NetBIOS TCP ports 135 through 139, passing all other traffic.

Technical Requirements:
- Check Ethernet, IPv4, and TCP bounds correctly
- Ensure (void *)(tcp + 1) <= data_end before reading tcp->dest
- Drop TCP packets with destination port >= 135 and <= 139
- Pass all other traffic safely
- GPL license and SEC("xdp")

Previous Implementation:
```c
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/in.h>
#include <linux/ip.h>
#include <linux/tcp.h>
#include <bpf/bpf_endian.h>
#include <bpf/bpf_helpers.h>

SEC("xdp")
int xdp_filter(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;
    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;
    if (ip->protocol != IPPROTO_TCP)
        return XDP_PASS;

    __u32 ip_len = (__u32)ip->ihl * 4;
    if (ip_len < sizeof(struct iphdr) || (void *)ip + ip_len > data_end)
        return XDP_PASS;

    struct tcphdr *tcp = (void *)ip + ip_len;
    // Fault: check is comparing (void *)tcp > data_end instead of (void *)(tcp + 1) > data_end
    if ((void *)tcp >= data_end)
        return XDP_PASS;

    __u16 dport = bpf_ntohs(tcp->dest);
    if (dport >= 135 && dport <= 139)
        return XDP_DROP;

    return XDP_PASS;
}

char LICENSE[] SEC("license") = "GPL";
```

