Task ID: repair_pfs_l1_syn_only_filter
Category: packet_filtering_security
Difficulty: level_1

Original Instruction:
Fix the behavioral bug in the XDP filter so it drops TCP SYN packets destined to port 80 while passing established TCP traffic (ACK, FIN, RST, etc.), UDP, and non-IP traffic.

Technical Requirements:
- Check bounds for Ethernet, IP, and TCP headers
- Check if TCP destination port is 80 (bpf_htons(80))
- Check if SYN flag is set ((tcp->syn) or (flags & 0x02)) and ACK flag is NOT set
- Return XDP_DROP for TCP SYN packets to port 80; return XDP_PASS for other packets
- GPL license and SEC("xdp")

Previous Implementation:
```c
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/in.h>
#include <linux/ip.h>
#include <linux/tcp.h>
#include <bpf/bpf_endian.h>
#include <bpf/bpf_helpers.h>

SEC("xdp")
int xdp_filter(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;
    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;
    if (ip->protocol != IPPROTO_TCP)
        return XDP_PASS;

    __u32 ip_len = (__u32)ip->ihl * 4;
    if (ip_len < sizeof(struct iphdr) || (void *)ip + ip_len > data_end)
        return XDP_PASS;

    struct tcphdr *tcp = (void *)ip + ip_len;
    if ((void *)(tcp + 1) > data_end)
        return XDP_PASS;

    if (tcp->dest == bpf_htons(80)) {
        // Behavioral Bug: inverted condition, dropping ACK instead of SYN
        if (tcp->syn)
            return XDP_PASS;
        else
            return XDP_DROP;
    }

    return XDP_PASS;
}

char LICENSE[] SEC("license") = "GPL";
```

